/* ===== Topical questions, Topic 6 (redox, reversible reactions, rates). Questions transcribed from the teacher's topical question sheets; answers are written for the hub, not official mark schemes. ===== */
const X3S="Cambridge IGCSE 0620 topical question, ";
const X3P=(f,n,t,m,q,ms)=>P(t,m,q,ms,X3S+f+", Question "+n);
const X3R=(n,t,m,q,ms)=>X3P("Redox",n,t,m,q,ms);
U[5].pp.push(
X3R(1,"Charge on the iron ion",2,"<p>Deduce the charge on the iron ion in each of these compounds.</p><p>FeF~3~ …………<br>Fe(NO~3~)~3~ …………  [2]</p>",
["FeF~3~: 3+ (1). Three F^−^ ions balance one iron ion.","Fe(NO~3~)~3~: 3+ (1). Three NO~3~^−^ ions balance one iron ion."]),
X3R(2,"Displacement of lead by zinc: reducing agent",2,"<p>Displacement reactions are redox reactions.</p><p style='text-align:center'>Zn + Pb^2+^ → Zn^2+^ + Pb</p><ol type='a'><li>Identify the reducing agent in this equation (the original asks you to ring it). [1]</li><li>Write down the change that shows oxidation (the original asks you to draw an arrow). [1]</li></ol>",
["(a) Zn (1): it gives electrons to Pb^2+^ so it is the reducing agent.","(b) Zn → Zn^2+^ (1): zinc loses two electrons, which is oxidation."]),
X3R(3,"Red lead oxide reduced by carbon",1,"<p>Lead is formed when red lead oxide, Pb~3~O~4~, is heated with carbon.</p><p style='text-align:center'>Pb~3~O~4~ + 4C → 3Pb + 4CO</p><p>Explain how this equation shows that Pb~3~O~4~ has been reduced. [1]</p>",
["Pb~3~O~4~ loses oxygen (1) (it becomes Pb)."]),
X3R(4,"Indigo dye: reduction and oxidation",2,"<p>Indigo is a blue dye.</p><p>When an alkaline solution of indigo undergoes reduction, it turns colourless.</p><ol type='a'><li>What is meant by the term <i>reduction</i>? [1]</li><li>A piece of white cloth is soaked in the colourless solution. When the cloth is left in the air it turns blue.<br>What type of chemical reaction occurs? Choose from: decomposition, fermentation, oxidation, polymerisation. [1]</li></ol>",
["(a) Loss of oxygen / gain of electrons (1).","(b) Oxidation (1): oxygen from the air oxidises the colourless form back to blue indigo."]),
X3R(5,"Carbon oxidised in the blast furnace",1,"<p>In the hotter parts of a blast furnace, carbon reacts with iron(III) oxide present in the iron ore.</p><p style='text-align:center'>3C + Fe~2~O~3~ → 3CO + 2Fe</p><p>How does this equation show that carbon is oxidised? [1]</p>",
["Carbon gains oxygen (1) (C becomes CO)."]),
X3R(6,"Reduction of XeO3F2",1,"<p>The compound XeO~3~F~2~ readily undergoes reduction.</p><p>What is meant by the term <i>reduction</i>? [1]</p>",
["Loss of oxygen / gain of electrons (1)."]),
X3R(7,"Reduction of ethanoic acid; Mr of ethanol",3,"<p>Ethanoic acid is an organic acid.</p><ol type='a'><li>The reduction of ethanoic acid produces ethanol.<br>What is meant by the term <i>reduction</i>? [1]</li><li>The molecular formula of ethanol is C~2~H~6~O.<br>Complete the table to calculate the relative molecular mass of ethanol. [2]"+TBL(["element","number of atoms","relative atomic mass","number × Ar"],[["carbon","2","12","2 × 12 = 24"],["hydrogen","",  "",""],["oxygen","","",""]],460)+"relative molecular mass = …………</li></ol>",
["(a) Loss of oxygen / gain of electrons (1).","(b) Hydrogen: 6 atoms, Ar = 1, 6 × 1 = 6; oxygen: 1 atom, Ar = 16, 1 × 16 = 16 (1) for the hydrogen and oxygen rows.","(b) Relative molecular mass = 24 + 6 + 16 = 46 (1)."]),
X3R(8,"Nickel(II) oxide reduced",1,"<p>Nickel can be obtained from nickel(II) oxide by heating it with a mixture of carbon monoxide and hydrogen.</p><p style='text-align:center'>2NiO + CO + H~2~ → 2Ni + CO~2~ + H~2~O</p><p>How does this equation show that the nickel(II) oxide is reduced? [1]</p>",
["NiO loses oxygen (1) (it becomes Ni)."]),
X3R(9,"Extraction of titanium",3,"<p>Titanium is extracted from an ore which contains titanium(IV) oxide, TiO~2~.</p><ol type='a'><li>Balance the chemical equation for the first step in this extraction.<br>TiO~2~ + ……C + ……Cl~2~ → TiCl~4~ + 2CO [2]</li><li>Explain why the conversion of carbon to carbon monoxide is an oxidation reaction. [1]</li></ol>",
["(a) 2 (1) for C.","(a) 2 (1) for Cl~2~: TiO~2~ + 2C + 2Cl~2~ → TiCl~4~ + 2CO.","(b) Carbon gains oxygen (1)."]),
X3R(10,"Lead extraction; transition element properties",3,"<p>Lead is extracted from an ore which contains lead(II) sulfide.</p><p>The ore is first heated in air.</p><p>The lead(II) oxide produced is then reduced with carbon.</p><p style='text-align:center'>PbO + C → Pb + CO</p><ol type='a'><li>How does this equation show that the lead(II) oxide is reduced? [1]</li><li>Lead is a metal in Group IV. Iron is a transition element.<br>Give <b>two</b> physical properties that are typical of transition elements. [2]</li></ol>",
["(a) PbO loses oxygen (1).","(b) Any two (2): high melting point; high density; hard / strong; good conductor of electricity and heat; malleable and ductile. One mark per correct property."]),
X3R(11,"Chlorine and sodium bromide",2,"<p>Chlorine reacts with aqueous sodium bromide.</p><p>The equation for the reaction is shown.</p><p style='text-align:center'>Cl~2~ + 2NaBr → 2NaCl + Br~2~</p><ol type='a'><li>State the type of reaction shown. [1]</li><li>Why is there <b>no</b> reaction between iodine and aqueous sodium bromide? [1]</li></ol>",
["(a) Displacement (1) (also accept redox).","(b) Iodine is less reactive than bromine (1), so it cannot displace bromine from its salt."]),
X3R(12,"Iron(II) sulfate with sodium hydroxide",4,"<p>When aqueous sodium hydroxide is added to aqueous iron(II) sulfate, a precipitate forms.</p><ol type='a'><li>What colour is this precipitate? [1]</li><li>Write the ionic equation for this reaction. Include state symbols. [3]</li></ol>",
["(a) Green (1).","(b) Fe^2+^(aq) + 2OH^−^(aq) → Fe(OH)~2~(s). Correct reactants (1).","(b) Correct product Fe(OH)~2~ and balancing (1).","(b) Correct state symbols (aq), (aq), (s) (1)."]),
X3R(13,"Iron(II) sulfate with aqueous ammonia",4,"<p>When aqueous ammonia is added to aqueous iron(II) sulfate a green precipitate is seen. This green precipitate turns red-brown at the surface.</p><ol type='a'><li>Name the green precipitate. [1]</li><li>Suggest why the green precipitate turns red-brown at the surface. [2]</li><li>State what happens when an excess of aqueous ammonia is added to the green precipitate. [1]</li></ol>",
["(a) Iron(II) hydroxide (1).","(b) Oxygen from the air oxidises it (1).","(b) Iron(II) is oxidised to iron(III), so iron(III) hydroxide forms (1).","(c) No change / the precipitate does not dissolve (1)."]),
X3R(14,"Iron(III) oxide heated with zinc",3,"<p>Iron can be obtained by heating iron(III) oxide with zinc powder.</p><p style='text-align:center'>Fe~2~O~3~ + 3Zn → 2Fe + 3ZnO</p><ol type='a'><li>What can be deduced about the reactivity of zinc from this reaction? [1]</li><li>The ionic equation for this reaction is shown.<br><span style='display:block;text-align:center'>2Fe^3+^ + 3Zn → 2Fe + 3Zn^2+^</span>Identify the oxidising agent in this reaction. Explain your answer in terms of electron transfer. [2]</li></ol>",
["(a) Zinc is more reactive than iron (1).","(b) Oxidising agent: Fe^3+^ (1).","(b) It gains electrons (from zinc) (1)."]),
X3R(15,"Ammonia to nitric acid",4,"<p>Ammonia is used in the manufacture of nitric acid.</p><ol type='a'><li>Balance the chemical equation for the first step in the process.<br>4NH~3~ + 5O~2~ → …..NO + 6H~2~O [1]</li><li>The reaction is exothermic. What is meant by the term <i>exothermic</i>? [1]</li><li>The NO produced in the first step then reacts with oxygen to produce nitrogen dioxide, NO~2~.<br><span style='display:block;text-align:center'>2NO + O~2~ → 2NO~2~</span>How does this equation show that NO is oxidised? [1]</li><li>Is nitrogen dioxide an acidic oxide or a basic oxide? Give a reason for your answer. [1]</li></ol>",
["(a) 4NO (1).","(b) The reaction releases heat energy to the surroundings (1).","(c) NO gains oxygen (1) (it becomes NO~2~).","(d) Acidic oxide, because it is a non-metal oxide (1)."]),
X3R(16,"Zinc and copper(II) sulfate",2,"<p>When a piece of zinc metal is added to copper(II) sulfate solution there is an immediate reaction.</p><p style='text-align:center'>Zn + CuSO~4~ → ZnSO~4~ + Cu</p><ol type='a'><li>Explain why zinc metal reacts with copper(II) sulfate. [1]</li><li>What type of reaction is this? [1]</li></ol>",
["(a) Zinc is more reactive than copper (1), so it displaces copper.","(b) Displacement (1) (also accept redox)."]),
X3R(17,"Magnesium and copper(II) sulfate: redox",4,"<p>When magnesium is added to aqueous copper(II) sulfate a reaction occurs.</p><p>The ionic equation for the reaction is shown.</p><p style='text-align:center'>Mg + Cu^2+^ → Mg^2+^ + Cu</p><ol type='a'><li>Give <b>one</b> change you would observe during this reaction. [1]</li><li>Explain why this is a redox reaction. [1]</li><li>Identify the oxidising agent in this reaction. Give a reason for your answer. [2]</li></ol>",
["(a) Any one (1): blue solution fades / becomes colourless; brown or pink solid forms; magnesium dissolves; temperature rises.","(b) Both oxidation and reduction happen (1): Mg loses electrons (oxidised) and Cu^2+^ gains electrons (reduced).","(c) Cu^2+^ (1).","(c) It gains electrons / it oxidises magnesium (1)."]),
X3R(18,"Blast furnace: iron ore and reduction of Fe3O4",4,"<p>Iron is extracted in a blast furnace using a mixture of iron ore, coke (carbon), air and calcium carbonate (limestone).</p><p>Magnetite is an ore of iron which contains a compound of iron with the formula Fe~3~O~4~.</p><ol type='a'><li>Give the name of another ore of iron. [1]</li><li>In the blast furnace Fe~3~O~4~ is reduced to Fe.<br>Complete the chemical equation for the reduction of Fe~3~O~4~.<br><span style='display:block;text-align:center'>Fe~3~O~4~ + 4CO → ……. Fe + ……. CO~2~</span>[2]</li><li>Explain how this equation shows that Fe~3~O~4~ is reduced. [1]</li></ol>",
["(a) Haematite (1) (Fe~2~O~3~).","(b) 3 Fe (1).","(b) 4 CO~2~ (1).","(c) Fe~3~O~4~ loses oxygen (1)."])
);

/* ---- Reversible reactions ---- */
const X3_EN=`<figure class="fig" style="max-width:340px"><svg viewBox="0 0 340 190" role="img" aria-label="Energy level diagram: 2SO2 + O2 at a higher energy level, 2SO3 at a lower level, with a downward arrow between them"><g stroke="currentColor" fill="none" stroke-width="1.6"><path d="M50 12V160H320"/><path d="M50 40H190"/><path d="M190 40V108" /><path d="M190 108H320"/></g><path d="M186 100l4 10 4-10z" fill="currentColor"/><g fill="currentColor" font-size="12" text-anchor="middle"><text x="120" y="32">2SO~2~(g) + O~2~(g)</text><text x="255" y="124">2SO~3~(g)</text><text x="185" y="182">progress of reaction</text><text transform="translate(16 100) rotate(-90)">energy</text></g></svg></figure>`.replace(/~2~/g,"₂").replace(/~3~/g,"₃");
const X3_PG=`<figure class="fig" style="max-width:340px"><svg viewBox="0 0 340 190" role="img" aria-label="Graph of yield of hydrogen iodide against pressure: two horizontal lines, the 500 degrees line above the 700 degrees line"><g stroke="currentColor" fill="none" stroke-width="1.6"><path d="M50 12V160H300"/><path d="M50 48H245"/><path d="M50 100H245"/></g><g fill="currentColor" font-size="12"><text x="252" y="52">500 °C</text><text x="252" y="104">700 °C</text><text x="150" y="182" text-anchor="middle">pressure</text><text transform="translate(18 130) rotate(-90)">yield of hydrogen iodide</text></g></svg></figure>`;
const X3V=(n,t,m,q,ms)=>X3P("Reversible reactions",n,t,m,q,ms);
U[5].pp.push(
X3V(1,"N2O4 / NO2 equilibrium in a gas syringe",6,"<p>The chemical equation shows the equilibrium between dinitrogen tetroxide (N~2~O~4~, a colourless gas) and nitrogen dioxide (NO~2~, a brown gas).</p><p style='text-align:center'>N~2~O~4~(g) ⇌ 2NO~2~(g)<br>colourless &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; brown</p><p>A mixture of dinitrogen tetroxide and nitrogen dioxide is allowed to reach equilibrium in a closed gas syringe.</p><ol type='a'><li>In chemistry, what is meant by the term <i>equilibrium</i>? [2]</li><li>If the equilibrium mixture is heated at constant pressure, a darker brown colour is seen inside the gas syringe.<br>What does this information indicate about the decomposition of dinitrogen tetroxide? Explain your answer in terms of the position of the equilibrium. [2]</li><li>Suggest what you would see if the pressure on the equilibrium mixture were increased at constant temperature.<br>Explain your answer in terms of the position of the equilibrium. [2]</li></ol>",
["(a) The rate of the forward reaction equals the rate of the backward reaction (1).","(a) The concentrations (amounts) of reactants and products stay constant, in a closed system (1).","(b) The decomposition of N~2~O~4~ is endothermic (1).","(b) Heating moves the position of equilibrium to the right, producing more brown NO~2~ (1).","(c) The mixture becomes paler brown (1) (after a brief darkening caused by compression).","(c) The equilibrium shifts to the left, to the side with fewer gas molecules (N~2~O~4~) (1)."]),
X3V(2,"Iron(III) chloride: balancing and the reversible sign",3,"<p>Iron reacts with chlorine to form iron(III) chloride, Fe~2~Cl~6~.</p><ol type='a'><li>Balance the chemical equation for this reaction.<br>……Fe + ……Cl~2~ → Fe~2~Cl~6~ [2]</li><li>At 400 °C Fe~2~Cl~6~ molecules decompose.<br>Fe~2~Cl~6~ ⇌ 2FeCl~3~<br>What is meant by the symbol ⇌ ? [1]</li></ol>",
["(a) 2 Fe (1).","(a) 3 Cl~2~ (1): 2Fe + 3Cl~2~ → Fe~2~Cl~6~.","(b) The reaction is reversible: it can go in both directions (1)."]),
X3V(3,"Anhydrous copper(II) sulfate",2,"<p>Anhydrous copper(II) sulfate is used to test for water.</p><p style='text-align:center'>CuSO~4~ + 5H~2~O ⇌ CuSO~4~.5H~2~O<br>anhydrous &nbsp; copper(II) sulfate &nbsp;&nbsp;&nbsp; hydrated copper(II) sulfate</p><ol type='a'><li>What is meant by the symbol ⇌? [1]</li><li>How can hydrated copper(II) sulfate be changed into anhydrous copper(II) sulfate? [1]</li></ol>",
["(a) The reaction is reversible (it can go forwards and backwards) (1).","(b) Heat it (1) to drive off the water."]),
X3V(4,"Iron(II) sulfate crystals losing water",2,"<p>When green iron(II) sulfate is heated it loses its water of crystallisation. The reaction is reversible.</p><ol type='a'><li>Complete the following equation by writing the sign for a reversible reaction in the box.<br>FeSO~4~.7H~2~O ☐ FeSO~4~ + 7H~2~O<br>(green) &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; (white) [1]</li><li>Use the information in the equation to suggest how to change white iron(II) sulfate into green iron(II) sulfate. [1]</li></ol>",
["(a) ⇌ (1).","(b) Add water (1)."]),
X3V(5,"Calcium chloride: water of crystallisation",2,"<p>Calcium chloride absorbs water vapour.</p><p>When calcium chloride is heated, it loses its water of crystallisation.</p><p>Complete the symbol equation for this reaction. Include the sign for a reversible reaction.</p><p style='text-align:center'>CaCl~2~.6H~2~O …… CaCl~2~ + ……… [2]</p>",
["Reversible sign ⇌ (1).","6H~2~O (1): CaCl~2~.6H~2~O ⇌ CaCl~2~ + 6H~2~O."]),
X3V(6,"The Contact process",6,"<p>Sulfuric acid is manufactured using the Contact process. This manufacture involves four stages.</p><ol type='a'><li><b>Stage 1</b> involves the combustion of sulfur to form sulfur dioxide.<br>Write the chemical equation for <b>stage 1</b>. [1]</li><li>The equation for <b>stage 2</b> is shown.<br><span style='display:block;text-align:center'>2SO~2~(g) + O~2~(g) ⇌ 2SO~3~(g)</span>The reaction can reach equilibrium.<br>Explain what is meant by the term <i>equilibrium</i>. [2]</li><li>The energy level diagram for the forward reaction in <b>stage 2</b> is shown.<br>"+X3_EN+"Explain what the diagram shows about the energy changes in the forward reaction. [2]</li><li>In <b>stage 3</b> sulfur trioxide, SO~3~, is converted to oleum, H~2~S~2~O~7~.<br>In <b>stage 4</b> oleum reacts to form sulfuric acid, H~2~SO~4~.<br>State what oleum reacts with in <b>stage 4</b>. [1]</li></ol>",
["(a) S + O~2~ → SO~2~ (1).","(b) The rate of the forward reaction equals the rate of the backward reaction (1).","(b) The concentrations of reactants and products stay constant (1).","(c) The products are at a lower energy than the reactants (1).","(c) So energy is released to the surroundings: the forward reaction is exothermic (1).","(d) Water (1)."]),
X3V(7,"Dehydration by concentrated sulfuric acid",2,"<p>Concentrated sulfuric acid is a dehydrating agent which can chemically remove water from substances.</p><p>Both hydrated copper(II) sulfate crystals and sucrose (a sugar), C~12~H~22~O~11~, can be completely dehydrated by concentrated sulfuric acid.</p><p>Name the solid product formed in each case.</p><p>hydrated copper(II) sulfate crystals …………<br>sucrose …………  [2]</p>",
["Hydrated copper(II) sulfate gives anhydrous copper(II) sulfate (white solid) (1).","Sucrose gives carbon (a black solid) (1)."]),
X3V(8,"PCl3 and Cl2: effect of pressure",2,"<p>Gaseous phosphorus(III) chloride, PCl~3~, reacts with gaseous chlorine to form gaseous phosphorus(V) chloride, PCl~5~.</p><p>Under certain conditions the reaction reaches equilibrium.</p><p style='text-align:center'>PCl~3~(g) + Cl~2~(g) ⇌ PCl~5~(g)</p><p>State and explain the effect, if any, on the <b>position of equilibrium</b> if the pressure is increased. All other conditions are unchanged. [2]</p>",
["The position of equilibrium moves to the right (1).","There are fewer gas molecules (2 moles) on the right than on the left (3 moles) (1)."]),
X3V(9,"Haber process",7,"<p>Ammonia is an important chemical.</p><p>Ammonia is manufactured by the Haber process. The reaction is reversible.</p><ol type='a'><li>What is the sign for a reversible reaction? [1]</li><li>State the essential conditions for the manufacture of ammonia by the Haber process starting from hydrogen and nitrogen. Include a chemical equation to show the reaction which occurs. [5]</li><li>Name <b>one</b> raw material which is a source of the hydrogen used in the Haber process. [1]</li></ol>",
["(a) ⇌ (1).","(b) Iron catalyst (1).","(b) Temperature of about 450 °C (accept 400 to 500 °C) (1).","(b) Pressure of about 200 atmospheres (accept 150 to 300 atm) (1).","(b) Equation: correct formulae N~2~ + H~2~ and NH~3~ (1).","(b) Equation balanced: N~2~ + 3H~2~ ⇌ 2NH~3~ (1).","(c) Natural gas (methane) (1). Accept steam or crude oil."]),
X3V(10,"Esterification equilibrium",4,"<p>The reaction between ethanoic acid and ethanol reaches equilibrium.</p><p style='text-align:center'>CH~3~COOH + CH~3~CH~2~OH ⇌ CH~3~COOCH~2~CH~3~ + H~2~O</p><ol type='a'><li>The reaction between ethanoic acid and ethanol is exothermic.<br>State and explain the effect, if any, of increasing the temperature on the amount of ester at equilibrium. [2]</li><li>State and explain the effect, if any, of removing water from the mixture on the amount of ester at equilibrium. [2]</li></ol>",
["(a) The amount of ester decreases (1).","(a) The position of equilibrium moves to the left, in the endothermic direction, because the forward reaction is exothermic (1).","(b) The amount of ester increases (1).","(b) The position of equilibrium moves to the right to replace the water that was removed (1)."]),
X3V(11,"Hydrogen and iodine: yield graphs",3,"<p>Hydrogen gas reacts with iodine gas. The equation is shown.</p><p style='text-align:center'>H~2~(g) + I~2~(g) ⇌ 2HI(g)</p><p>The reaction is reversible and can reach equilibrium.</p><p>The graphs show how pressure affects the yield of hydrogen iodide, HI, at two different temperatures.</p>"+X3_PG+"<ol type='a'><li>Explain why the yield at 500 °C does <b>not</b> change as the pressure is increased. [1]</li><li>What can you conclude from the difference in the yield of hydrogen iodide at the <b>two</b> temperatures shown? Explain your answer. [2]</li></ol>",
["(a) There are the same number of gas molecules (2 moles) on each side of the equation (1), so pressure does not shift the equilibrium.","(b) The forward reaction is exothermic (1).","(b) The yield is lower at the higher temperature because high temperature favours the endothermic backward reaction (1)."]),
X3V(12,"Cobalt chloride equilibrium",3,"<p>When cobalt(II) chloride is added to water an equilibrium is established.</p><p style='text-align:center'>[CoCl~4~]^2−^ + 6H~2~O ⇌ [Co(H~2~O)~6~]^2+^ + 4Cl^−^<br>blue &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; pink</p><ol type='a'><li>A student adds water to a blue solution containing [CoCl~4~]^2−^ ions.<br>Describe what the student observes. Give a reason for your answer in terms of the position of the equilibrium. [2]</li><li>Another student cools a blue solution containing [CoCl~4~]^2−^. The blue solution turns pink.<br>What does this information indicate about the forward reaction? [1]</li></ol>",
["(a) The solution turns from blue to pink (1).","(a) Extra water (a reactant) moves the position of equilibrium to the right (1).","(b) The forward reaction is exothermic (1): cooling favours the exothermic direction."]),
X3V(13,"Hydrogen iodide equilibrium in a sealed syringe",2,"<p>Hydrogen and iodine react together in a reversible reaction. Hydrogen iodide is formed.</p><p style='text-align:center'>H~2~(g) + I~2~(g) ⇌ 2HI(g)<br>colourless gas &nbsp; purple gas &nbsp; colourless gas</p><p>The forward reaction is exothermic.</p><p>A gas syringe containing an equilibrium mixture of hydrogen, iodine and hydrogen iodide gases was sealed and heated to 250 °C. The equilibrium mixture was a pale purple colour.</p><p>The plunger of the gas syringe was pressed in while the end of the gas syringe was blocked. This increased the pressure. The position of the equilibrium did <b>not</b> change. The colour of the gaseous mixture turned darker purple.</p><ol type='a'><li>Give a reason why the position of the equilibrium did <b>not</b> change. [1]</li><li>Suggest why the gaseous mixture turned darker purple, even though the position of the equilibrium did <b>not</b> change. [1]</li></ol>",
["(a) There are the same number of gas molecules on both sides of the equation (1).","(b) The same amount of iodine is squeezed into a smaller volume, so its concentration is higher (1)."]),
X3V(14,"NO2 / N2O4: pressure and temperature",5,"<p>Nitrogen dioxide, NO~2~, exists in equilibrium with dinitrogen tetroxide, N~2~O~4~.</p><p>Nitrogen dioxide is brown and dinitrogen tetroxide is colourless.</p><p style='text-align:center'>2NO~2~(g) ⇌ N~2~O~4~(g)<br>brown &nbsp;&nbsp;&nbsp;&nbsp; colourless</p><ol type='a'><li>A sample of nitrogen dioxide and dinitrogen tetroxide at equilibrium was placed in a closed gas syringe.<br>The syringe plunger was pushed in. This increased the pressure in the gas syringe. The temperature was kept constant.<br>State how the colour of the gas in the syringe changed. Explain your answer in terms of the position of the equilibrium. [3]</li><li>A sealed tube containing nitrogen dioxide and dinitrogen tetroxide at equilibrium was cooled in an ice bath at constant pressure. The contents of the tube became paler.<br>Suggest an explanation for this observation in terms of the position of the equilibrium. [2]</li></ol>",
["(a) The colour becomes paler (lighter brown) (1), after a brief darkening caused by compression.","(a) The position of equilibrium moves to the right (1).","(a) The right-hand side has fewer gas molecules (1 mole instead of 2) (1).","(b) Cooling moves the position of equilibrium to the right, forming more colourless N~2~O~4~ (1).","(b) The forward reaction is exothermic, so cooling favours it (1)."]),
X3V(15,"Chromate and dichromate equilibrium",5,"<p>Some chemical reactions are reversible.</p><p>Aqueous potassium chromate(VI), K~2~CrO~4~, is a yellow solution.</p><p>Aqueous potassium dichromate(VI), K~2~Cr~2~O~7~, is an orange solution.</p><p>The two compounds interconvert when the pH of the solution changes.</p><p style='text-align:center'>2K~2~CrO~4~ + H~2~SO~4~ ⇌ K~2~Cr~2~O~7~ + K~2~SO~4~ + H~2~O<br>yellow &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; orange</p><p>Solution <b>Y</b> is a mixture of aqueous potassium chromate(VI) and aqueous potassium dichromate(VI) at equilibrium.</p><ol type='a'><li>Explain, in terms of the position of the equilibrium, what you would <b>see</b> if sulfuric acid were added to solution <b>Y</b>. [2]</li><li>Explain, in terms of the position of the equilibrium, what you would <b>see</b> if sodium hydroxide were added to solution <b>Y</b>. [3]</li></ol>",
["(a) The solution becomes more orange (1).","(a) Adding sulfuric acid (a reactant) moves the position of equilibrium to the right (1).","(b) The solution becomes more yellow (1).","(b) Sodium hydroxide neutralises (removes) the acid, so the concentration of H~2~SO~4~ falls (1).","(b) The position of equilibrium moves to the left (1)."]),
X3V(16,"Uranium hydride",3,"<p>Uranium reacts with hydrogen to form uranium hydride, UH~3~. The reaction is reversible.</p><p>Complete the chemical equation for this reaction by:</p><ul><li>balancing the equation</li><li>drawing the symbol for a reversible reaction in the box.</li></ul><p style='text-align:center'>2U + ……H~2~ ☐ ……UH~3~ [3]</p>",
["3 in front of H~2~ (1).","2 in front of UH~3~ (1).","⇌ in the box (1): 2U + 3H~2~ ⇌ 2UH~3~."]),
X3V(17,"Phosgene equilibrium",4,"<p>Chlorine reacts with carbon monoxide to produce phosgene gas, COCl~2~(g). A catalyst is used.</p><p style='text-align:center'>Cl~2~(g) + CO(g) ⇌ COCl~2~(g)</p><p>The reaction is exothermic.</p><p>Describe and explain the effect, if any, on the position of equilibrium when:</p><ol type='a'><li>the pressure is increased [2]</li><li>the temperature is increased. [2]</li></ol>",
["(a) The position of equilibrium moves to the right (1).","(a) There are fewer gas molecules on the right (1 mole against 2 moles) (1).","(b) The position of equilibrium moves to the left (1).","(b) The backward reaction is endothermic, and heating favours the endothermic direction (1)."]),
X3V(18,"Hot iron and steam",1,"<p>Hot iron reacts with steam. The reaction is reversible.</p><p>Complete the equation by writing the symbol for a reversible reaction.</p><p style='text-align:center'>3Fe + 4H~2~O ………… Fe~3~O~4~ + 4H~2~ [1]</p>",
["⇌ (1)."]),
X3V(19,"Decomposition of hydrogen iodide: cooling",1,"<p>Hydrogen iodide, HI, decomposes into iodine and hydrogen. The reaction is reversible.</p><p style='text-align:center'>2HI(g) ⇌ I~2~(g) + H~2~(g)<br>colourless gas &nbsp; purple gas &nbsp; colourless gas</p><p>A gas syringe containing a mixture of hydrogen iodide, iodine and hydrogen gases was sealed. After reaching equilibrium the mixture was a pale purple colour.</p><p>The forward reaction is endothermic.</p><p>State what happens to the position of equilibrium when the temperature is decreased. [1]</p>",
["The position of equilibrium moves to the left (1), because the backward reaction is exothermic, so cooling favours it."]),
X3V(20,"Hydrogen iodide: pushing in the plunger",2,"<p>Hydrogen iodide, HI, decomposes into iodine and hydrogen. The reaction is reversible.</p><p style='text-align:center'>2HI(g) ⇌ I~2~(g) + H~2~(g)<br>colourless gas &nbsp; purple gas &nbsp; colourless gas</p><p>A gas syringe containing a mixture of hydrogen iodide, iodine and hydrogen gases was sealed. After reaching equilibrium the mixture was a pale purple colour.</p><p>The plunger of the gas syringe is pushed in. The position of equilibrium does not change. The colour of the gaseous mixture turns darker purple.</p><p>The temperature remains constant.</p><ol type='a'><li>Explain why the position of equilibrium does <b>not</b> change. [1]</li><li>Suggest why the colour of the gaseous mixture turns darker purple even though the position of equilibrium does not change. [1]</li></ol>",
["(a) There are the same number of gas molecules on each side of the equation (1).","(b) The iodine is squeezed into a smaller volume, so its concentration is higher (1)."]),
X3V(21,"Rates when the temperature is decreased",2,"<p>Hydrogen iodide, HI, decomposes into iodine and hydrogen. The reaction is reversible.</p><p style='text-align:center'>2HI(g) ⇌ I~2~(g) + H~2~(g)<br>colourless gas &nbsp; purple gas &nbsp; colourless gas</p><p>A gas syringe containing a mixture of hydrogen iodide, iodine and hydrogen gases was sealed. After reaching equilibrium the mixture was a pale purple colour.</p><p>The forward reaction is endothermic.</p><p>State what happens to the rate of the forward reaction and the rate of the backward reaction when the temperature of the mixture is decreased.</p><p>rate of the forward reaction …………<br>rate of the backward reaction …………  [2]</p>",
["Rate of the forward reaction decreases (1).","Rate of the backward reaction decreases (1)."]),
X3V(22,"Magnesium sulfate crystals",1,"<p>A student prepares magnesium sulfate crystals, MgSO~4~, by adding excess magnesium to dilute sulfuric acid.</p><p>Magnesium sulfate crystals have the formula MgSO~4~•<i>x</i>H~2~O, where <i>x</i> is a whole number of molecules of water.</p><p>Name the term given to crystals containing molecules of water. [1]</p>",
["Hydrated (1)."]),
X3V(23,"The Haber process: facts",6,"<p>Ammonia is made in an industrial process starting with nitrogen.</p><p>The equation for the reaction is shown.</p><p style='text-align:center'>N~2~ + 3H~2~ ⇌ 2NH~3~</p><ol type='a'><li>Name the industrial process used to make ammonia. [1]</li><li>State the raw material from which nitrogen is obtained. [1]</li><li>State what is meant by the symbol ⇌. [1]</li><li>State the temperature and pressure used in this industrial process.<br>temperature = …………°C<br>pressure = ………… atm [2]</li><li>Name the catalyst used in this industrial process. [1]</li></ol>",
["(a) The Haber process (1).","(b) Air (1).","(c) The reaction is reversible (1).","(d) Temperature about 450 °C (accept 400 to 500 °C) (1).","(d) Pressure about 200 atm (accept 150 to 300 atm) (1).","(e) Iron (1)."]),
X3V(24,"Contact process: equilibrium",6,"<p>Sulfuric acid is manufactured by an industrial process. Sulfur is obtained from sulfur-containing metal ores.</p><p>The sulfur in the metal ore is converted to sulfur dioxide which is then oxidised to sulfur trioxide as shown.</p><p style='text-align:center'>2SO~2~(g) + O~2~(g) ⇌ 2SO~3~(g)</p><p>The reaction that produces sulfur trioxide is an equilibrium. The forward reaction is exothermic.</p><ol type='a'><li>Describe <b>two</b> features of an equilibrium. [2]</li><li>State the effect, if any, on the position of equilibrium when the following changes are made. Explain your answers.<br>temperature is increased<br>pressure is increased [4]</li></ol>",
["(a) The rate of the forward reaction equals the rate of the backward reaction (1).","(a) The concentrations of reactants and products stay constant (it is a closed system) (1).","(b) Temperature increased: the position moves to the left (1).","(b) The backward reaction is endothermic, which heating favours (1).","(b) Pressure increased: the position moves to the right (1).","(b) There are fewer gas molecules on the right (2 moles instead of 3) (1)."]),
X3V(25,"Calcium nitrate crystals",1,"<p>Calcium nitrate crystals are hydrated and have the formula Ca(NO~3~)~2~•<i>x</i>H~2~O where <i>x</i> is a whole number of molecules of water.</p><p>A student heats the crystals to remove the molecules of water.</p><p style='text-align:center'>Ca(NO~3~)~2~•<i>x</i>H~2~O(s) → Ca(NO~3~)~2~(s) + <i>x</i>H~2~O(g)</p><p>State the term used to describe the calcium nitrate after the molecules of water have been removed. [1]</p>",
["Anhydrous (1)."]),
X3V(26,"Haber process: temperature and pressure",4,"<p>Ammonia is made in an industrial process starting with nitrogen.</p><p>The equation for the reaction is shown.</p><p style='text-align:center'>N~2~ + 3H~2~ ⇌ 2NH~3~</p><p>The forward reaction is exothermic.</p><p>State the effect, if any, on the position of the equilibrium when the following changes are made. Explain your answers.</p><p>temperature is reduced<br>pressure is reduced [4]</p>",
["Temperature reduced: the position moves to the right (1).","The forward reaction is exothermic, so lowering the temperature favours it (1).","Pressure reduced: the position moves to the left (1).","There are more gas molecules on the left (4 moles instead of 2) (1)."])
);

/* ---- Rates of reaction ---- */
const X3_CURVE=(yl,xl,aria)=>`<figure class="fig" style="max-width:340px"><svg viewBox="0 0 340 200" role="img" aria-label="${aria}"><g stroke="currentColor" fill="none" stroke-width="1.6"><path d="M60 14V164H310"/><path d="M60 164C80 70 120 42 190 38H290" stroke-width="2.2"/></g><g fill="currentColor" font-size="12"><text x="185" y="190" text-anchor="middle">${xl}</text><text transform="translate(26 150) rotate(-90)">${yl}</text></g></svg></figure>`;
const X3_APP="<p><i>(The diagram shows a conical flask containing lumps of iron and sulfuric acid. A delivery tube leads from the flask to an upturned measuring cylinder full of water, standing in a trough of water, so that the hydrogen produced can be collected and its volume measured.)</i></p>";
const X3A=(n,t,m,q,ms)=>X3P("Rate (speed) of reaction",n,t,m,q,ms);
const X3_COLL=["Particles move faster and have more kinetic energy (1).","So they collide more frequently (1).","A greater proportion of the collisions have energy equal to or greater than the activation energy, so more collisions are successful (1)."];
U[5].pp.push(
X3A(1,"Catalyst: hydrogen peroxide",2,"<p>Oxygen is produced by the decomposition of hydrogen peroxide. Manganese(IV) oxide is the catalyst for this reaction.</p><p>What is meant by the term <i>catalyst</i>? [2]</p>",
["A substance that speeds up (increases the rate of) a reaction (1).","It is not used up / is chemically unchanged at the end of the reaction (1)."]),
X3A(2,"Catalyst: oxidation of ethanol",2,"<p>Ethanol can be oxidised by hydrogen peroxide to form ethanal, CH~3~CHO. A catalyst for this reaction is Fe^3+^.</p><p>What is meant by the term <i>catalyst</i>? [2]</p>",
["A substance that speeds up (increases the rate of) a reaction (1).","It is not used up / is chemically unchanged at the end of the reaction (1)."]),
X3A(3,"Catalyst: esterification",2,"<p>Concentrated sulfuric acid is a catalyst for the reaction between ethanoic acid and ethanol.</p><p>What is meant by the term <i>catalyst</i>? [2]</p>",
["A substance that speeds up (increases the rate of) a reaction (1).","It is not used up / is chemically unchanged at the end of the reaction (1)."]),
X3A(4,"Why temperature increases the rate",4,"<p>The rate of a reaction can be increased by increasing the temperature.</p><p>Explain why increasing the temperature increases the rate of reaction. [4]</p>",
["The particles gain kinetic energy and move faster (1).","They collide more often (more frequent collisions) (1).","A greater proportion of particles have energy equal to or greater than the activation energy (1).","So there are more successful collisions in a given time (1)."]),
X3A(5,"Ethene and steam: equilibrium and rate",6,"<p>Ethene gas reacts with steam to form gaseous ethanol.</p><p style='text-align:center'>C~2~H~4~(g) + H~2~O(g) ⇌ CH~3~CH~2~OH(g)</p><p>The reaction can reach a position of equilibrium. The forward reaction is exothermic.</p><ol type='a'><li>State and explain the effect of increasing the pressure on the <b>position of equilibrium</b>. All other conditions are unchanged. [2]</li><li>Increasing the pressure of a gas increases its concentration.<br>State and explain the effect of increasing the pressure on the <b>rate</b> of the reaction. All other conditions are unchanged. [2]</li><li>State and explain the effect of increasing the temperature on the position of equilibrium. All other conditions are unchanged. [2]</li></ol>",
["(a) The position of equilibrium moves to the right (1).","(a) There are fewer gas molecules on the right (1 mole instead of 2 moles) (1).","(b) The rate increases (1).","(b) The particles are closer together, so there are more frequent collisions (1).","(c) The position of equilibrium moves to the left (1).","(c) The backward reaction is endothermic, and heating favours the endothermic direction (1)."]),
X3A(6,"Lumps of copper(II) carbonate",2,"<p>The first step in the preparation of hydrated copper(II) sulfate is to add powdered copper(II) carbonate to dilute sulfuric acid.</p><p>When the reaction is done using lumps of copper(II) carbonate instead of powder, the rate of reaction decreases. All other conditions are kept the same.</p><p>Give a reason for this. Explain your answer in terms of particles. [2]</p>",
["Lumps have a smaller surface area than the powder (1).","Fewer particles are exposed to the acid, so there are fewer collisions per second (1)."]),
X3A(7,"Ethanoic acid manufacture: effect of changes",4,"<p>Ethanoic acid is manufactured from methanol and carbon monoxide.</p><p style='text-align:center'>CH~3~OH(g) + CO(g) ⇌ CH~3~COOH(g)</p><p>The process is done at 200 °C and 30 atmospheres pressure.</p><p>The forward reaction is exothermic.</p><p>Complete the table using only the words <i>increases</i>, <i>decreases</i> or <i>no change</i>. [4]</p>"+TBL(["","effect on the rate of the forward reaction","effect on the equilibrium yield of CH~3~COOH(g)"],[["adding a catalyst","","no change"],["increasing the temperature","",""],["decreasing the pressure","decreases",""]],520),
["Adding a catalyst: rate of the forward reaction increases (1).","Increasing the temperature: rate increases (1).","Increasing the temperature: equilibrium yield decreases, because the forward reaction is exothermic (1).","Decreasing the pressure: equilibrium yield decreases, because the position moves to the side with more gas molecules (the left) (1)."]),
X3A(8,"Iron lumps and sulfuric acid: method",7,"<p>A student investigated the reaction of lumps of iron with sulfuric acid.</p><p style='text-align:center'>Fe(s) + H~2~SO~4~(aq) → FeSO~4~(aq) + H~2~(g)</p><p>She used the apparatus shown below.</p>"+X3_APP+"<ol type='a'><li>Describe how this apparatus can be used to investigate the rate of this reaction. [3]</li><li>Describe how the rate of reaction would differ if smaller lumps of iron were used. All other conditions remain the same. [1]</li><li>The student investigated the effect of temperature on the reaction rate.<br>State <b>three</b> factors which the student should keep the same in each experiment. [3]</li></ol>",
["(a) Measure the volume of hydrogen collected in the measuring cylinder (1).","(a) Read the volume at regular time intervals, using a stopwatch (1).","(a) The faster the volume increases, the faster the reaction (rate = volume ÷ time) (1).","(b) The rate would be faster (1).","(c) Any three of these (3): concentration of the acid; volume of the acid; mass of iron; size of the lumps of iron (surface area); same apparatus."]),
X3A(9,"Rate of iron with acid at different temperatures",2,"<p>A student investigated the reaction of lumps of iron with sulfuric acid.</p><p style='text-align:center'>Fe(s) + H~2~SO~4~(aq) → FeSO~4~(aq) + H~2~(g)</p><p>She used the apparatus shown below.</p>"+X3_APP+"<p>The table shows how the rate of reaction changed with temperature.</p>"+TBL(["temperature / °C","rate of reaction in cm^3^ / s"],[["20","2.2"],["30","4.4"],["40","8.8"],["50","17.6"]],320)+"<p>Use the information in the table to describe how the rate of reaction changed with temperature. [2]</p>",
["The rate increases as the temperature increases (1).","The rate doubles for every 10 °C rise in temperature (1)."]),
X3A(10,"Hydrogen iodide equilibrium: effect of heating",3,"<p>Hydrogen and iodine react together in a reversible reaction. Hydrogen iodide is formed.</p><p style='text-align:center'>H~2~(g) + I~2~(g) ⇌ 2HI(g)<br>colourless gas &nbsp; purple gas &nbsp; colourless gas</p><p>The forward reaction is exothermic.</p><p>A gas syringe containing an equilibrium mixture of hydrogen, iodine and hydrogen iodide gases was sealed and heated to 250 °C. The equilibrium mixture was a pale purple colour.</p><p>The temperature of the gas syringe was increased to 300 °C.</p><ol type='a'><li>What happened to the <b>position</b> of the equilibrium when the temperature of the gas syringe was increased from 250 °C to 300 °C? [1]</li><li>What happened to the <b>rate</b> of the forward reaction and the <b>rate</b> of the backward reaction when the temperature of the gas syringe was increased from 250 °C to 300 °C?<br>rate of the forward reaction …………<br>rate of the backward reaction ………… [2]</li></ol>",
["(a) The position of equilibrium moves to the left (1), because the backward reaction is endothermic.","(b) The rate of the forward reaction increases (1).","(b) The rate of the backward reaction increases (1)."]),
X3A(11,"Cobalt and hydrochloric acid: collision theory",4,"<p>Cobalt reacts with dilute hydrochloric acid to make the salt cobalt(II) chloride. Bubbles of hydrogen gas are produced.</p><ol type='a'><li>The rate of reaction of cobalt with dilute hydrochloric acid can be made faster by heating the acid or by increasing its concentration.<br>State <b>one</b> other way to make the rate of reaction faster. [1]</li><li>Use collision theory to explain how heating the dilute hydrochloric acid makes the rate of reaction faster. [3]</li></ol>",
["(a) Any one (1): use smaller pieces or powdered cobalt (larger surface area); add a catalyst.","(b) "+X3_COLL[0],"(b) "+X3_COLL[1],"(b) "+X3_COLL[2]]),
X3A(12,"Iron powder and hydrochloric acid: initial rate",3,"<p>A student investigates the rate of reaction of 1 g of iron powder with 25 cm^3^ of hydrochloric acid of concentration 2.0 mol / dm^3^. The temperature is 20 °C.</p><p>What effect do the following have on the initial rate of this reaction?</p><ol type='a'><li>Using hydrochloric acid of concentration 1.2 mol / dm^3^. All other conditions are kept the same. [1]</li><li>Using a piece of iron of mass 1 g. All other conditions are kept the same. [1]</li><li>Carrying out the experiment at 25 °C. All other conditions are kept the same. [1]</li></ol>",
["(a) The rate decreases (1): the acid is less concentrated.","(b) The rate decreases (1): a piece has a smaller surface area than powder.","(c) The rate increases (1): a higher temperature."]),
X3A(13,"Decomposition of hydrogen peroxide: oxygen volume graph",9,"<p>Oxygen is produced by the decomposition of hydrogen peroxide. Manganese(IV) oxide is the catalyst for this reaction.</p><p>A student measures the volume of oxygen produced at regular time intervals using the apparatus shown. Large lumps of manganese(IV) oxide are used.</p><p><i>(The diagram shows a conical flask containing aqueous hydrogen peroxide and lumps of manganese(IV) oxide catalyst, connected by a delivery tube to a gas syringe.)</i></p><p>A graph of the results is shown.</p>"+X3_CURVE("volume of oxygen produced / cm³","time / s","Graph of volume of oxygen against time: a curve that rises steeply then levels off")+"<ol type='a'><li>What happens to the <b>rate</b> of this reaction as time increases? In your answer, explain why the rate changes in this way. [4]</li><li>The experiment is repeated using the same mass of manganese(IV) oxide. Powdered manganese(IV) oxide is used instead of large lumps. All other conditions stay the same.<br>Describe how the graph would change. (The original asks you to sketch the new curve on the axes.) [2]</li><li>In terms of particles, explain what happens to the rate of this reaction when the temperature is increased. [3]</li></ol>",
["(a) The rate decreases as time increases (1) (the curve becomes less steep until it is flat).","(a) The concentration of hydrogen peroxide falls as it is used up (1).","(a) So there are fewer particles per unit volume, and fewer collisions per second (1).","(a) The rate is zero when all the hydrogen peroxide has been used up, and the curve is flat (1).","(b) The curve is steeper at the start (1) (faster rate, because powder has a larger surface area).","(b) The curve levels off at the same final volume (1) (the amount of hydrogen peroxide is unchanged).","(c) "+X3_COLL[0],"(c) "+X3_COLL[1],"(c) "+X3_COLL[2]]),
X3A(14,"PCl3 and Cl2: equilibrium and rate",9,"<p>PCl~3~ reacts with chlorine, Cl~2~, to form PCl~5~. This reaction is exothermic and reaches an equilibrium.</p><p style='text-align:center'>PCl~3~(g) + Cl~2~(g) ⇌ PCl~5~(g)</p><ol type='a'><li>Describe <b>two</b> features of an equilibrium. [2]</li><li>State the effect, if any, on the position of this equilibrium when the following changes are made. Explain your answers.<br>temperature is increased<br>pressure is increased [4]</li><li>Explain, in terms of particles, what happens to the rate of the forward reaction when the reaction mixture is heated. [3]</li></ol>",
["(a) The rate of the forward reaction equals the rate of the backward reaction (1).","(a) The concentrations of reactants and products stay constant (1).","(b) Temperature increased: the position moves to the left (1).","(b) The backward reaction is endothermic, and heating favours it (1).","(b) Pressure increased: the position moves to the right (1).","(b) There are fewer gas molecules on the right (1 mole instead of 2 moles) (1).","(c) "+X3_COLL[0],"(c) "+X3_COLL[1],"(c) "+X3_COLL[2]]),
X3A(15,"Marble and hydrochloric acid: higher temperature",5,"<p>A student investigated the progress of the reaction between dilute hydrochloric acid, HCl, and an excess of large pieces of marble, CaCO~3~, using the apparatus shown.</p><p><i>(The diagram shows a conical flask containing dilute hydrochloric acid and an excess of large pieces of marble, connected by a delivery tube to a gas syringe.)</i></p><p>The experiment was repeated at a higher temperature. All other conditions were kept the same.</p><p>Describe and explain, in terms of collisions between particles, the effect of using a higher temperature on the time taken for the reaction to finish. [5]</p>",
["The reaction finishes in a shorter time (1).","The particles move faster / have more kinetic energy (1).","They collide more frequently (1).","A greater proportion of the particles have energy equal to or greater than the activation energy (1).","So more collisions are successful in each second (1)."]),
X3A(16,"Hydrogen iodide: concentration against time",3,"<p>Hydrogen gas reacts with iodine gas. The equation is shown.</p><p style='text-align:center'>H~2~(g) + I~2~(g) ⇌ 2HI(g)</p><p>The reaction is reversible and can reach equilibrium.</p><p>The graph shows how the concentration of hydrogen iodide, HI, changes after hydrogen gas and iodine gas are mixed together in a sealed container.</p>"+X3_CURVE("concentration of hydrogen iodide","time","Graph of concentration of hydrogen iodide against time: a curve that rises steeply then levels off")+"<ol type='a'><li>When is the rate of reaction fastest? [1]</li><li>The reaction was repeated at the same temperature and pressure but in the presence of a catalyst.<br>Describe how the graph would change when a catalyst is used. (The original asks you to draw the new curve on the same axes.) [2]</li></ol>",
["(a) At the start (time = 0) (1), when the concentrations of hydrogen and iodine are highest (the curve is steepest).","(b) The curve is steeper at the start (1), so equilibrium is reached sooner.","(b) The curve levels off at the same concentration of HI (1), because a catalyst does not change the position of equilibrium."]),
X3A(17,"Copper(II) oxide and acid: collision theory",4,"<p>Copper(II) oxide reacts with dilute hydrochloric acid.</p><p style='text-align:center'>CuO(s) + 2HCl(aq) → CuCl~2~(aq) + H~2~O(l)</p><p>The rate of the reaction can be increased by increasing the concentration of the hydrochloric acid or by heating it.</p><ol type='a'><li>In terms of collisions, explain why increasing the concentration of the hydrochloric acid increases the rate of the reaction. [2]</li><li>In terms of collisions, explain why heating the hydrochloric acid increases the rate of the reaction. [2]</li></ol>",
["(a) There are more acid particles in each unit of volume (1).","(a) So there are more frequent collisions between the acid particles and the copper(II) oxide (1).","(b) The particles move faster, so they collide more often (1).","(b) A greater proportion of collisions have energy equal to or greater than the activation energy, so more are successful (1)."]),
X3A(18,"Cobalt and hydrochloric acid: collision theory (second version)",4,"<p>Cobalt reacts with dilute hydrochloric acid to make the salt cobalt(II) chloride. Bubbles of hydrogen gas are produced.</p><ol type='a'><li>The rate of reaction of cobalt with dilute hydrochloric acid can be made faster by heating the acid or by increasing its concentration.<br>State <b>one</b> other way to make the rate of reaction faster. [1]</li><li>Use collision theory to explain how heating the dilute hydrochloric acid makes the rate of reaction faster. [3]</li></ol>",
["(a) Any one (1): use smaller pieces or powdered cobalt (larger surface area); add a catalyst.","(b) "+X3_COLL[0],"(b) "+X3_COLL[1],"(b) "+X3_COLL[2]])
);

/* ---- Rates (continued): graphs recreated from the sheet ---- */
function X3_PLOT(pts,o){
  const W=360,H=250,L=62,R=14,T=12,B=44,pw=W-L-R,ph=H-T-B;
  const x0=o.xmin||0,x1=o.xmax,y0=o.ymin||0,y1=o.ymax;
  const X=v=>L+(v-x0)/(x1-x0)*pw,Y=v=>T+ph-(v-y0)/(y1-y0)*ph;
  const P=pts.map(p=>[X(p[0]),Y(p[1])]);
  let d="M"+P[0][0].toFixed(1)+" "+P[0][1].toFixed(1);
  for(let i=0;i<P.length-1;i++){const p0=P[Math.max(0,i-1)],p1=P[i],p2=P[i+1],p3=P[Math.min(P.length-1,i+2)];
    d+="C"+(p1[0]+(p2[0]-p0[0])/6).toFixed(1)+" "+(p1[1]+(p2[1]-p0[1])/6).toFixed(1)+" "+(p2[0]-(p3[0]-p1[0])/6).toFixed(1)+" "+(p2[1]-(p3[1]-p1[1])/6).toFixed(1)+" "+p2[0].toFixed(1)+" "+p2[1].toFixed(1)}
  let g="",tk="";
  (o.xt||[]).forEach(v=>{g+=`<path d="M${X(v)} ${T}V${T+ph}" stroke="currentColor" stroke-opacity=".16"/>`;tk+=`<text x="${X(v)}" y="${T+ph+14}" text-anchor="middle">${v}</text>`});
  (o.yt||[]).forEach(v=>{g+=`<path d="M${L} ${Y(v)}H${L+pw}" stroke="currentColor" stroke-opacity=".16"/>`;tk+=`<text x="${L-6}" y="${Y(v)+4}" text-anchor="end">${v}</text>`});
  return `<figure class="fig" style="max-width:380px"><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${o.aria}">${g}<path d="M${L} ${T}V${T+ph}H${L+pw}" fill="none" stroke="currentColor" stroke-width="1.6"/><path d="${d}" fill="none" stroke="currentColor" stroke-width="2.2"/><g fill="currentColor" font-size="11">${tk}<text x="${L+pw/2}" y="${H-6}" text-anchor="middle" font-size="12">${o.xl}</text><text transform="translate(13 ${T+ph/2}) rotate(-90)" text-anchor="middle" font-size="12">${o.yl}</text></g></svg></figure>`}
const X3_G19=X3_PLOT([[0,0],[30,42],[60,68],[90,83],[120,90],[240,90]],{xmax:240,ymax:150,xt:[0,30,60,90,120,150,180,210,240],yt:[0,50,100,150],xl:"time / s",yl:"volume of gas produced / cm³",aria:"Graph of volume of gas against time: rises to 90 cm³ at 120 s then flat"});
const X3_G27=X3_PLOT([[0,0],[10,32],[20,59],[30,79],[40,91.5],[50,96],[70,96]],{xmax:70,ymax:120,xt:[0,10,20,30,40,50,60,70],yt:[0,20,40,60,80,100,120],xl:"time / s",yl:"volume of hydrogen / cm³",aria:"Graph of volume of hydrogen against time: rises to about 96 cm³ at 50 s then flat"});
const X3_G28=X3_PLOT([[0,0],[10,10],[20,19],[40,30],[60,37],[80,40],[100,41],[140,41]],{xmax:140,ymax:60,xt:[0,20,40,60,80,100,120,140],yt:[0,10,20,30,40,50,60],xl:"time / s",yl:"volume of carbon dioxide / cm³",aria:"Graph of volume of carbon dioxide against time: rises to 41 cm³ by 100 s then flat"});
const X3_G29=X3_PLOT([[0,200],[10,199.7],[20,199.5],[40,199.3],[60,199.16],[80,199.07],[100,199.01],[110,199],[140,199]],{xmax:140,ymin:198.8,ymax:200,xt:[0,20,40,60,80,100,120,140],yt:[198.8,199,199.2,199.4,199.6,199.8,200],xl:"time / s",yl:"mass of reaction mixture / g",aria:"Graph of mass of reaction mixture against time: falls from 200.0 g to 199.0 g by about 110 s then flat"});
const X3_G33=X3_PLOT([[0,100.25],[100,100.155],[200,100.11],[300,100.087],[400,100.077],[450,100.075],[700,100.075]],{xmax:700,ymin:100,ymax:100.25,xt:[0,100,200,300,400,500,600,700],yt:[100,100.05,100.1,100.15,100.2,100.25],xl:"time / s",yl:"mass of reaction mixture / g",aria:"Graph of mass of reaction mixture against time: falls from 100.25 g to 100.075 g by about 450 s then flat"});
const X3_G37=X3_PLOT([[0,0],[20,15],[40,25],[60,32],[80,36.5],[100,39],[140,39]],{xmax:140,ymax:60,xt:[0,20,40,60,80,100,120,140],yt:[0,10,20,30,40,50,60],xl:"time / s",yl:"volume of oxygen gas / cm³",aria:"Graph of volume of oxygen against time: rises to 39 cm³ at 100 s then flat"});
const X3_MASS=X3_PLOT([[0,100],[20,78],[45,50],[75,28],[110,14],[160,9],[220,8]],{xmax:220,ymin:0,ymax:110,xt:[],yt:[],xl:"time / s",yl:"mass of the flask and contents / g",aria:"Graph of mass of flask and contents against time: falls steeply at first, then levels off"});
const X3_VOL=X3_CURVE("volume of carbon dioxide gas","time","Graph of volume of carbon dioxide against time: a curve that rises steeply then levels off");
const X3_APP2="<p><i>(The diagram shows a conical flask containing the reactants, connected by a delivery tube to a gas syringe.)</i></p>";
U[5].pp.push(
X3A(19,"Marble and acid: smaller pieces",2,"<p>A student investigated the progress of the reaction between dilute hydrochloric acid, HCl, and an excess of large pieces of marble, CaCO~3~, using a gas syringe.</p>"+X3_APP2+"<p>A graph of the volume of gas produced against time is shown.</p>"+X3_G19+"<p>The experiment was repeated using the same mass of smaller pieces of marble. All other conditions were kept the same.</p><p>Describe how the graph would change when smaller pieces are used. (The original asks you to draw the new curve on the grid.) [2]</p>",
["The curve is steeper at the start (1), because smaller pieces have a larger surface area, so the rate is faster.","The curve levels off at the same volume, 90 cm^3^ (1), because the mass of marble is unchanged."]),
X3A(20,"Calcium carbonate lumps: rate as the reaction proceeds",3,"<p>A student investigates the rate of reaction between lumps of calcium carbonate and dilute hydrochloric acid using a gas syringe.</p><p style='text-align:center'>CaCO~3~(s) + 2HCl(aq) → CaCl~2~(aq) + CO~2~(g) + H~2~O(l)</p><p>The calcium carbonate was in excess.</p>"+X3_APP2+"<p>What happens to the rate of reaction as the reaction proceeds? Explain your answer. [3]</p>",
["The rate decreases (1).","The concentration of the hydrochloric acid falls as the acid is used up (1).","So there are fewer acid particles in a given volume and fewer collisions per second (1)."]),
X3A(21,"Calcium carbonate lumps: higher temperature",4,"<p>A student investigates the rate of reaction between lumps of calcium carbonate and dilute hydrochloric acid using a gas syringe.</p><p style='text-align:center'>CaCO~3~(s) + 2HCl(aq) → CaCl~2~(aq) + CO~2~(g) + H~2~O(l)</p><p>The calcium carbonate was in excess.</p>"+X3_APP2+"<p>The student repeated the experiment at a higher temperature. All other conditions were kept the same. The student found that the rate of reaction increased.</p><p>Explain, in terms of collisions, why the rate of reaction increased. [4]</p>",
["The particles have more kinetic energy and move faster (1).","They collide more frequently (1).","A greater proportion of the particles have energy equal to or greater than the activation energy (1).","So there are more successful collisions per second (1)."]),
X3A(22,"Hydrogen iodide: concentration, temperature and rates",5,"<p>Hydrogen gas reacts with iodine gas. The equation is shown.</p><p style='text-align:center'>H~2~(g) + I~2~(g) ⇌ 2HI(g)</p><p>The reaction is reversible and can reach equilibrium.</p><p>A mixture of hydrogen gas and iodine gas is allowed to reach equilibrium.</p><ol type='a'><li>Increasing the pressure of a gas increases its concentration.<br>State and explain the effect of increasing the pressure on the <b>rate</b> of the forward reaction. [2]</li><li>State and explain the effect of increasing the temperature on the <b>rate</b> of the reverse reaction. [3]</li></ol>",
["(a) The rate increases (1).","(a) The particles are closer together, so they collide more frequently (1).","(b) The rate of the reverse reaction increases (1).","(b) The particles move faster, so they collide more often (1).","(b) A greater proportion of collisions have energy equal to or greater than the activation energy (1)."]),
X3A(23,"Nitric acid manufacture: first stage",9,"<p>Some of the ammonia made by the Haber process is converted into nitric acid.</p><p>The first stage of this process is the oxidation of ammonia to make nitrogen monoxide.</p><p style='text-align:center'>4NH~3~(g) + 5O~2~(g) ⇌ 4NO(g) + 6H~2~O(g)</p><p>The process is carried out at 900 °C and a pressure of 5 atmospheres using an alloy of platinum and rhodium as a catalyst.</p><p>The forward reaction is exothermic.</p><ol type='a'><li>State the meaning of the term <i>catalyst</i>. [2]</li><li>State the meaning of the term <i>oxidation</i>. [1]</li><li>Complete the table using the words <b>increase</b>, <b>decrease</b> or <b>no change</b>. [4]"+TBL(["","effect on the rate of the forward reaction","effect on the equilibrium yield of NO(g)"],[["increasing the temperature","",""],["increasing the pressure","",""]],520)+"</li><li>Nitrogen monoxide, NO, is converted into nitrogen dioxide, NO~2~.<br><span style='display:block;text-align:center'>2NO(g) + O~2~(g) → 2NO~2~(g)</span>The nitrogen dioxide reacts with oxygen and water to produce nitric acid as the only product.<br>Write a chemical equation for this reaction. [2]</li></ol>",
["(a) A substance that speeds up (increases the rate of) a reaction (1).","(a) It is not used up / is unchanged at the end of the reaction (1).","(b) Gain of oxygen (or loss of electrons) (1).","(c) Increasing the temperature: rate increase (1).","(c) Increasing the temperature: yield decrease (1), because the forward reaction is exothermic.","(c) Increasing the pressure: rate increase (1).","(c) Increasing the pressure: yield decrease (1), because there are more gas molecules on the right (10 moles against 9 moles).","(d) Correct formulae: NO~2~, O~2~, H~2~O and HNO~3~ (1).","(d) Balanced: 4NO~2~ + O~2~ + 2H~2~O → 4HNO~3~ (1)."]),
X3A(24,"Methanol manufacture",5,"<p>Methanol is made industrially by reacting carbon monoxide with hydrogen. The gases react at a temperature of 250 °C and a pressure of 75 atmospheres.</p><p style='text-align:center'>CO(g) + 2H~2~(g) ⇌ CH~3~OH(g)</p><p>The forward reaction is exothermic.</p><ol type='a'><li>Suggest a source of hydrogen for this industrial process. [1]</li><li>Complete the table using only the words <i>increases</i>, <i>decreases</i> or <i>no change</i>. [4]"+TBL(["","effect on the rate of the reverse reaction","effect on the equilibrium yield of CH~3~OH(g)"],[["adding a catalyst","","no change"],["increasing the temperature","increases",""],["decreasing the pressure","",""]],520)+"</li></ol>",
["(a) Natural gas (methane) (1). Accept steam or crude oil.","(b) Adding a catalyst: rate of the reverse reaction increases (1).","(b) Increasing the temperature: yield decreases (1), because the forward reaction is exothermic.","(b) Decreasing the pressure: rate of the reverse reaction decreases (1).","(b) Decreasing the pressure: yield decreases (1), because the position moves to the side with more gas molecules (the left)."]),
X3A(25,"Contact process: catalyst, temperature and pressure",7,"<p>The Contact process changes sulfur dioxide into sulfur trioxide.</p><p style='text-align:center'>2SO~2~(g) + O~2~(g) ⇌ 2SO~3~(g)</p><ul><li>the forward reaction is exothermic</li><li>temperature 400 to 450 °C</li><li>low pressure 1 to 10 atmospheres</li><li>catalyst vanadium(V) oxide</li></ul><ol type='a'><li>What is the formula of vanadium(V) oxide? [1]</li><li>Vanadium(V) oxide is an efficient catalyst at any temperature in the range 400 to 450 °C. Scientists are looking for an alternative catalyst which is efficient at 300 °C.<br>What would be the advantage of using a lower temperature? [2]</li><li>The process does not use a high pressure because of the extra expense.<br>Suggest <b>two</b> advantages of using a high pressure. Explain your suggestions. [4]</li></ol>",
["(a) V~2~O~5~ (1).","(b) The equilibrium yield of SO~3~ would be higher (1), because the forward reaction is exothermic.","(b) Less energy (fuel) is needed, so costs are lower (1).","(c) Higher yield (1), because the position of equilibrium moves to the right, to the side with fewer gas molecules (1).","(c) Faster rate (1), because the particles are closer together so there are more frequent collisions (1)."]),
X3A(26,"Iron and sulfuric acid: concentration",3,"<p>The rate of reaction of iron with sulfuric acid can be determined by measuring the time taken to produce 20 cm^3^ of hydrogen.</p><p>A student measured the time taken to produce 20 cm^3^ of hydrogen using three different concentrations of sulfuric acid.</p><p>In each experiment the student used: 1 g of iron powder, the same temperature, the same volume of sulfuric acid.</p><p>The results are shown in the table.</p>"+TBL(["concentration of acid in mol / dm^3^","time / s"],[["0.1","33"],["0.2","17"],["0.5","8"]],340)+"<ol type='a'><li>Use the information in the table to describe how the rate of reaction changes with the concentration of sulfuric acid. [1]</li><li>Describe the effect of each of the following on the rate of this reaction with 0.5 mol / dm^3^ of sulfuric acid. All other conditions stay the same.<br>Larger pieces of iron are used.<br>The temperature is increased. [2]</li></ol>",
["(a) The rate increases as the concentration increases (1) (it is roughly proportional: doubling the concentration halves the time).","(b) Larger pieces: the rate decreases (1), smaller surface area.","(b) Temperature increased: the rate increases (1)."]),
X3A(27,"Zinc powder and hydrochloric acid: graph",6,"<p>A student investigated the reaction of zinc powder with excess dilute hydrochloric acid in the absence of a catalyst.</p><p style='text-align:center'>Zn + 2HCl → ZnCl~2~ + H~2~</p><p>The student measured the volume of hydrogen gas produced at 10 second intervals.</p><p>The graph shows the results.</p>"+X3_G27+"<p>Answer these questions using information from the graph.</p><ol type='a'><li>Deduce the volume of hydrogen produced in the first 25 seconds of the experiment. [1]</li><li>Explain why no more hydrogen is produced after 50 seconds. [1]</li><li>The experiment is repeated using a catalyst. All other conditions stay the same.<br>Describe how the graph would change. (The original asks you to draw the new line on the grid.) [2]</li><li>Describe what effect the following changes have on the rate of the reaction. All other conditions stay the same.<br>The concentration of hydrochloric acid is decreased.<br>Large pieces of zinc are used. [2]</li></ol>",
["(a) About 70 cm^3^ (1). Accept 68 to 72.","(b) All the zinc has reacted (1) (the acid is in excess, so the zinc is the limiting reactant).","(c) The line is steeper at the start (1).","(c) It levels off at the same volume, about 96 cm^3^ (1), because a catalyst does not change the amount of product.","(d) Concentration decreased: the rate decreases (1).","(d) Large pieces of zinc: the rate decreases (1), smaller surface area."]),
X3A(28,"Magnesium carbonate and nitric acid: graph",6,"<p>A student investigates the rate of reaction of large pieces of magnesium carbonate with an excess of dilute nitric acid.</p><p style='text-align:center'>MgCO~3~ + 2HNO~3~ → Mg(NO~3~)~2~ + CO~2~ + H~2~O</p><p>The graph shows how the volume of carbon dioxide changes with time.</p>"+X3_G28+"<ol type='a'><li>After how many seconds did the reaction finish? [1]</li><li>From the graph, deduce the volume of carbon dioxide produced during the first 50 seconds of the experiment. [1]</li><li>The experiment is repeated using smaller pieces of the same mass of magnesium carbonate. All other conditions are kept the same.<br>Describe how the graph would change. (The original asks you to draw the new line on the grid.) [2]</li><li>How does increasing the temperature affect the rate of this reaction? All other conditions are kept the same. [1]</li><li>How does decreasing the concentration of nitric acid affect the rate of this reaction? All other conditions are kept the same. [1]</li></ol>",
["(a) About 100 s (1) (accept 100 to 110).","(b) About 34 cm^3^ (1) (accept 33 to 35).","(c) The line is steeper at the start (1).","(c) It levels off at the same volume, 41 cm^3^ (1).","(d) The rate increases (1).","(e) The rate decreases (1)."]),
X3A(29,"Calcium carbonate: loss in mass",6,"<p>A student investigates the rate of reaction of small pieces of calcium carbonate with an excess of hydrochloric acid of concentration 1 mol / dm^3^.</p><p style='text-align:center'>CaCO~3~(s) + 2HCl(aq) → CaCl~2~(aq) + CO~2~(g) + H~2~O(l)</p><p>The graph shows how the mass of the reaction mixture changes with time.</p>"+X3_G29+"<ol type='a'><li>State why the reaction mixture decreases in mass. [1]</li><li>Calculate the loss in mass during the first 40 seconds of the experiment. [1]</li><li>The experiment is repeated using hydrochloric acid of concentration 2 mol / dm^3^. All other conditions are kept the same.<br>Describe how the graph would change. (The original asks you to draw the new line on the grid.) [2]</li><li>In the experiment, when 2.00 g of calcium carbonate is used, the loss in mass of the reaction mixture is 0.88 g. All other conditions are kept the same.<br>Calculate the loss in mass when 0.50 g of calcium carbonate is used. [1]</li><li>The experiment is repeated using the same mass of different sized pieces of calcium carbonate (powder, small pieces, large pieces). All other conditions are kept the same.<br>Complete the table by writing the sizes of the pieces of calcium carbonate in the first column. [1]"+TBL(["size of pieces of calcium carbonate","initial rate of loss in mass in g / s"],[["","0.005"],["","0.030"],["","0.100"]],380)+"</li></ol>",
["(a) Carbon dioxide gas escapes from the flask (1).","(b) 200.0 − 199.3 = 0.7 g (1).","(c) The line is steeper at the start (1).","(c) It ends at the same mass, 199.0 g (1), because the amount of calcium carbonate is unchanged (the acid was already in excess).","(d) 0.50 ÷ 2.00 × 0.88 = 0.22 g (1).","(e) 0.005 large pieces, 0.030 small pieces, 0.100 powder (1): smaller pieces have a larger surface area and react faster."]),
X3A(30,"Marble and acid: shape of the graph",3,"<p>A student investigated the progress of the reaction between dilute hydrochloric acid, HCl, and an excess of large pieces of marble, CaCO~3~, using a gas syringe.</p>"+X3_APP2+"<p>A graph of the volume of gas produced against time is shown.</p>"+X3_G19+"<ol type='a'><li>How does the shape of the graph show that the rate of reaction decreased as the reaction progressed? [1]</li><li>Why did the rate of reaction decrease as the reaction progressed? [1]</li><li>After how many seconds did the reaction finish? [1]</li></ol>",
["(a) The gradient (slope) of the curve decreases (it gets less steep) (1).","(b) The concentration of the acid decreases as it is used up (1).","(c) 120 s (1)."]),
X3A(31,"Measurements to find a rate",2,"<p>A student investigates the rate of reaction between lumps of calcium carbonate and dilute hydrochloric acid using a gas syringe.</p><p style='text-align:center'>CaCO~3~(s) + 2HCl(aq) → CaCl~2~(aq) + CO~2~(g) + H~2~O(l)</p><p>The calcium carbonate was in excess.</p>"+X3_APP2+"<p>Which measurements should the student make during the reaction to determine the rate of reaction? [2]</p>",
["The volume of gas collected in the gas syringe (1).","The time taken (at regular time intervals) (1)."]),
X3A(32,"Two ways to speed up a reaction",2,"<p>A student investigates the rate of reaction between lumps of calcium carbonate and dilute hydrochloric acid using a gas syringe.</p><p style='text-align:center'>CaCO~3~(s) + 2HCl(aq) → CaCl~2~(aq) + CO~2~(g) + H~2~O(l)</p><p>The calcium carbonate was in excess.</p>"+X3_APP2+"<p>Apart from using a higher temperature, suggest <b>two</b> other methods of increasing the rate of this reaction. [2]</p>",
["Use smaller pieces (or powdered) calcium carbonate (1).","Use a higher concentration of hydrochloric acid (1)."]),
X3A(33,"Calcium carbonate: mass graph and rate changes",5,"<p>Calcium carbonate reacts with dilute hydrochloric acid.</p><p>The graph below shows how the mass of the reaction mixture changes with time. The calcium carbonate was in excess and large pieces of calcium carbonate were used.</p>"+X3_G33+"<ol type='a'><li>At what time was the reaction just complete? [1]</li><li>Calculate the total loss in mass of the reaction mixture in this experiment. [1]</li><li>How does the rate of reaction change when:<br>smaller pieces of calcium carbonate are used,<br>the temperature is decreased,<br>the concentration of hydrochloric acid is decreased? [3]</li></ol>",
["(a) About 450 s (1) (accept 440 to 460), where the line becomes flat.","(b) 100.25 − 100.075 = 0.175 g (1) (accept 0.17 to 0.18).","(c) Smaller pieces: the rate increases (1).","(c) Temperature decreased: the rate decreases (1).","(c) Concentration decreased: the rate decreases (1)."]),
X3A(34,"Magnesium carbonate: rate decreases with time",5,"<p>A student adds excess large pieces of magnesium carbonate, MgCO~3~, to dilute hydrochloric acid, HCl, and measures the volume of carbon dioxide gas, CO~2~, given off.</p><p>The graph shows how the volume of carbon dioxide gas changes with time.</p>"+X3_VOL+"<ol type='a'><li>Describe how the graph shows that the rate of this reaction decreases as time increases. [1]</li><li>Explain, in terms of particles, why the rate of this reaction decreases as time increases. [2]</li><li>The student repeats the experiment using powdered MgCO~3~ instead of large pieces. All other conditions stay the same.<br>Describe how the graph would change. (The original asks you to draw the line on the grid.) [2]</li></ol>",
["(a) The gradient of the curve decreases (it gets less steep until it is flat) (1).","(b) The concentration of the acid falls as it is used up, so there are fewer acid particles in a given volume (1).","(b) So there are fewer collisions per second (1).","(c) The line is steeper at the start (1), because powder has a larger surface area.","(c) It levels off at the same volume (1)."]),
X3A(35,"Metal oxide catalysts for hydrogen peroxide",2,"<p>Some metal oxides catalyse the decomposition of hydrogen peroxide.</p><p>The table shows the time taken to produce 20 cm^3^ of oxygen gas using three different metal oxide powders as catalysts. All other conditions stay the same.</p>"+TBL(["metal oxide","time taken to produce 20 cm^3^ of oxygen gas / s"],[["iron(III) oxide","26"],["lead(IV) oxide","12"],["manganese(IV) oxide","15"]],420)+"<ol type='a'><li>Put the three oxides in order of their ability to catalyse the reaction. Put the <b>best</b> catalyst first. [1]</li><li>The experiments with the metal oxide catalysts used powdered oxide.<br>Describe the effect on the rate of decomposition of hydrogen peroxide when large pieces of catalyst are used instead of powdered catalyst. All other conditions stay the same. [1]</li></ol>",
["(a) Lead(IV) oxide, manganese(IV) oxide, iron(III) oxide (1). The shortest time means the best catalyst.","(b) The rate decreases (1), because large pieces have a smaller surface area."]),
X3A(36,"Hydrogen peroxide: mass loss and temperature",5,"<p>A student investigates the decomposition of hydrogen peroxide in the presence of a catalyst of manganese(IV) oxide.</p><p style='text-align:center'>2H~2~O~2~(aq) → 2H~2~O(l) + O~2~(g)</p><p><i>(The diagram shows a conical flask of aqueous hydrogen peroxide, with a loose cotton wool plug in its neck, standing on a balance. The catalyst of manganese(IV) oxide is in a small dish beside it.)</i></p><p>The student uses this method: the catalyst is added to the aqueous hydrogen peroxide; the stop-clock is started; the mass of the flask and contents is recorded at regular time intervals.</p><p>A graph of the mass of the flask and contents against time is shown.</p>"+X3_MASS+"<p>The student repeats the experiment at a higher temperature. All other conditions stay the same. The rate of reaction increases.</p><ol type='a'><li>Explain, in terms of collisions between particles, why the rate of reaction increases at a higher temperature. [3]</li><li>Describe how the graph would change at the higher temperature. (The original asks you to draw the line on the graph.) [2]</li></ol>",
["(a) "+X3_COLL[0],"(a) "+X3_COLL[1],"(a) "+X3_COLL[2],"(b) The line falls more steeply at the start (1).","(b) It levels off at the same final mass (1)."]),
X3A(37,"Enzyme and the decomposition of hydrogen peroxide",6,"<p>The rate of decomposition of aqueous hydrogen peroxide, H~2~O~2~, is increased by an enzyme.</p><p style='text-align:center'>2H~2~O~2~ → 2H~2~O + O~2~</p><p>The rate of reaction is found by measuring the volume of oxygen gas given off as the reaction proceeds.</p><p>The results are shown on the graph.</p>"+X3_G37+"<ol type='a'><li>(i) Deduce the volume of oxygen gas released when the reaction is complete. [1]<br>(ii) Deduce the volume of oxygen gas produced 50 seconds from the start of the reaction. [1]</li><li>The experiment was repeated using hydrogen peroxide of a higher concentration. All other conditions stayed the same.<br>Describe how the graph would change. (The original asks you to draw the new line on the grid.) [2]</li><li>Describe the effect each of the following has on the rate of decomposition of hydrogen peroxide.<br>(i) The reaction is carried out at a lower temperature. All other conditions stay the same. [1]<br>(ii) The reaction is carried out without an enzyme. All other conditions stay the same. [1]</li></ol>",
["(a)(i) 39 cm^3^ (1).","(a)(ii) About 28.5 cm^3^ (1). Accept 28 to 29.","(b) The line is steeper at the start (1).","(b) It levels off at a higher volume (1), because there is more hydrogen peroxide to decompose.","(c)(i) The rate decreases (1).","(c)(ii) The rate decreases (1)."]),
X3A(38,"Zinc and copper(II) sulfate",7,"<p>When zinc granules are added to aqueous copper(II) sulfate, a reaction occurs.</p><p>During the reaction, a red-pink solid is formed and the solution becomes colourless.</p><ol type='a'><li>Name the red-pink solid. [1]</li><li>Name the colourless solution. [1]</li><li>Explain, in terms of particles, why the rate of this reaction increases when the temperature is increased. [3]</li><li>Suggest two <b>other</b> ways of increasing the rate of this reaction. [2]</li></ol>",
["(a) Copper (1).","(b) Zinc sulfate (1).","(c) "+X3_COLL[0],"(c) "+X3_COLL[1],"(c) "+X3_COLL[2],"(d) Any two (2): use smaller granules or powdered zinc; use a higher concentration of copper(II) sulfate."]),
X3A(39,"Mass loss during decomposition of hydrogen peroxide",3,"<p>A student investigates the decomposition of hydrogen peroxide in the presence of a catalyst of manganese(IV) oxide.</p><p style='text-align:center'>2H~2~O~2~(aq) → 2H~2~O(l) + O~2~(g)</p><p><i>(The diagram shows a conical flask of aqueous hydrogen peroxide, with a loose cotton wool plug in its neck, standing on a balance. The catalyst of manganese(IV) oxide is in a small dish beside it.)</i></p><p>The student uses this method: the catalyst is added to the aqueous hydrogen peroxide; the stop-clock is started; the mass of the flask and contents is recorded at regular time intervals.</p><p>A graph of the mass of the flask and contents against time is shown.</p>"+X3_MASS+"<ol type='a'><li>Suggest why the mass of the flask and contents decreases as time increases. [1]</li><li>Describe what happens to the rate of the reaction as time increases. [2]</li></ol>",
["(a) Oxygen gas escapes from the flask (1).","(b) The rate decreases (1) (the curve becomes less steep).","(b) The rate becomes zero when the line is flat, because all the hydrogen peroxide has been used up (1)."]),
X3A(40,"Catalyst: manganese(IV) oxide",2,"<p>A student investigates the decomposition of hydrogen peroxide in the presence of a catalyst of manganese(IV) oxide.</p><p style='text-align:center'>2H~2~O~2~(aq) → 2H~2~O(l) + O~2~(g)</p><p>State the meaning of the term <i>catalyst</i>. [2]</p>",
["A substance that speeds up (increases the rate of) a reaction (1).","It is not used up / is chemically unchanged at the end of the reaction (1)."])
);
